namespace GeoNex.Services.Topografia;

using NetTopologySuite.Geometries;
using GeoNex.Topografia.Domain;

public sealed class TopografiaProcessingService {
    public ImovelCertificacaoSigef ProcessarPoligonoParaSigef(Geometry geom, string codCredenciado, int fusoUtm, string nome, string titular) {
        if (geom is not Polygon && geom is not MultiPolygon)
            throw new ArgumentException("A geometria deve ser um poligono fechado.");
        var poly = geom is MultiPolygon mp ? (Polygon)mp.Geometries[0] : (Polygon)geom;
        var coords = poly.ExteriorRing.Coordinates;
        if (NetTopologySuite.Algorithm.Orientation.IsCCW(coords)) Array.Reverse(coords);
        var imovel = new ImovelCertificacaoSigef {
            Denominacao = nome,
            ProprietarioNome = titular,
            CredenciadoCodigoIncra = codCredenciado,
            FusoUtm = fusoUtm,
            AreaHectares = Math.Abs(poly.Area) / 10000.0,
            AreaMetrosQuadrados = Math.Abs(poly.Area),
            PerimetroMetros = poly.ExteriorRing.Length
        };
        int total = coords.Length - 1;
        for (int i = 0; i < total; i++) {
            var c = coords[i];
            var v = new VerticeTopografico {
                Indice = i + 1,
                Codigo = $"{codCredenciado}-M-{(i + 1):D4}",
                Tipo = TipoVertice.M,
                EsteUtm = c.X,
                NorteUtm = c.Y,
                AltitudeOrtometrica = double.IsNaN(c.Z) ? 0.0 : c.Z
            };
            ConverterUtmParaGeodesica(c.X, c.Y, fusoUtm, true, out double lat, out double lon);
            v.LatitudeDecimal = lat;
            v.LongitudeDecimal = lon;
            v.LatitudeGms = FormatarParaPadraoIncra(lat, true);
            v.LongitudeGms = FormatarParaPadraoIncra(lon, false);
            imovel.Vertices.Add(v);
        }
        for (int i = 0; i < total; i++) {
            var v1 = imovel.Vertices[i];
            var v2 = imovel.Vertices[(i + 1) % total];
            double dX = v2.EsteUtm - v1.EsteUtm;
            double dY = v2.NorteUtm - v1.NorteUtm;
            double dist = Math.Sqrt(dX * dX + dY * dY);
            double azimuteRad = Math.Atan2(dX, dY);
            if (azimuteRad < 0) azimuteRad += 2 * Math.PI;
            double azimuteGraus = azimuteRad * (180.0 / Math.PI);
            imovel.Segmentos.Add(new SegmentoPerimetro {
                Ordem = i + 1,
                De = v1,
                Para = v2,
                DistanciaPlanaMetros = dist,
                DistanciaGeodesicaMetros = dist,
                AzimutePlanoGraus = azimuteGraus,
                AzimuteFormatadoGms = FormatarDmsMemorial(azimuteGraus),
                TipoLimite = TipoLimite.LA,
                DescricaoLimite = "Cerca",
                NomeConfrontante = "A DEFINIR"
            });
        }
        return imovel;
    }
    public static void ConverterUtmParaGeodesica(double este, double norte, int fuso, bool hemisferioSul, out double lat, out double lon) {
        // Serie analitica de Redfearn e Coticchia-Surace GRS80/SIRGAS2000
        const double a = 6378137.0;
        const double e2 = 0.00669438002290;
        const double k0 = 0.9996;
        double ePrime2 = e2 / (1.0 - e2);
        double x = este - 500000.0;
        double y = hemisferioSul ? norte - 10000000.0 : norte;
        double m = y / k0;
        double e1 = (1.0 - Math.Sqrt(1.0 - e2)) / (1.0 + Math.Sqrt(1.0 - e2));
        double mu = m / (a * (1.0 - e2 / 4.0 - 3.0 * e2 * e2 / 64.0 - 5.0 * Math.Pow(e2, 3) / 256.0));
        double j1 = 3.0 * e1 / 2.0 - 27.0 * Math.Pow(e1, 3) / 32.0;
        double j2 = 21.0 * e1 * e1 / 16.0 - 55.0 * Math.Pow(e1, 4) / 32.0;
        double j3 = 151.0 * Math.Pow(e1, 3) / 96.0;
        double fp = mu + j1 * Math.Sin(2 * mu) + j2 * Math.Sin(4 * mu) + j3 * Math.Sin(6 * mu);
        double sinFp = Math.Sin(fp);
        double cosFp = Math.Cos(fp);
        double tanFp = Math.Tan(fp);
        double c1 = ePrime2 * cosFp * cosFp;
        double t1 = tanFp * tanFp;
        double n1 = a / Math.Sqrt(1.0 - e2 * sinFp * sinFp);
        double r1 = a * (1.0 - e2) / Math.Pow(1.0 - e2 * sinFp * sinFp, 1.5);
        double d = x / (n1 * k0);
        double latRad = fp - (n1 * tanFp / r1) * (d * d / 2.0 - (5.0 + 3.0 * t1 + 10.0 * c1 - 4.0 * c1 * c1 - 9.0 * ePrime2) * Math.Pow(d, 4) / 24.0);
        lat = latRad * (180.0 / Math.PI);
        double lonRad = (d - (1.0 + 2.0 * t1 + c1) * Math.Pow(d, 3) / 6.0) / cosFp;
        double centralMeridian = (fuso * 6 - 183) * (Math.PI / 180.0);
        lon = (centralMeridian + lonRad) * (180.0 / Math.PI);
    }
    public static string FormatarParaPadraoIncra(double val, bool isLat) {
        char sinal = val < 0 ? '-' : '+';
        double abs = Math.Abs(val);
        int g = (int)Math.Floor(abs);
        double rm = (abs - g) * 60.0;
        int m = (int)Math.Floor(rm);
        double s = (rm - m) * 60.0;
        return $"{sinal}{g:00} {m:00} {s:00.000}".Replace('.', ',');
    }
    public static string FormatarDmsMemorial(double ang) {
        double norm = (ang % 360.0 + 360.0) % 360.0;
        int g = (int)Math.Floor(norm);
        double rm = (norm - g) * 60.0;
        int m = (int)Math.Floor(rm);
        double s = (rm - m) * 60.0;
        return $"{g:00}°{m:00}'{s:00.0}\"";
    }
}

